    (2375.6, '5', ' ', [(1230.5,'1.0','5'), (146.5,'99.0','5')]),
    (2579.9, '5', ' ', [(2158.1,'23','1'), (0.0,'100','')]),
    (2610.6, '5', ' ', [(2158.1,'8','1'), (1887.2,'3','1'), (1230.5,'24','2'), (665.7,'18','1'), (146.5,'35','1')]),
    (2721.4, '7', ' ', [(1230.5,'2','1'), (665.7,'6','1'), (461.2,'49','2'), (146.5,'18','1'), (0.0,'14','1')]),
    (3128.9, '5', ' ', [(2158.1,'67','12'), (0.0,'100','')]),
    (3333.9, '10', ' ', [(665.7,'22','6'), (461.2,'11','6')]),
    (3383.6, '6', ' ', [(1230.5,'16','3'), (665.7,'27','2'), (461.2,'26','2'), (146.5,'31','2')]),
    (3545.2, '8', ' ', [(1230.5,'4','2'), (146.5,'96','2')]),
    (3600.3, '8', ' ', [(2721.4,'46','2'), (2375.6,'7','1'), (2181.2,'2','LT'), (146.5,'47','2')]),
    (3631.1, '8', ' ', [(2375.6,'55','2'), (146.5,'45','2')]),
    (3645.6, '15', ' ', [(146.5,'100','')]),
    (3659.4, '15', '?', [(2158.1,'100','')]),
    (3773.9, '10', ' ', [(0.0,'100','')]),
    (3941.2, '15', ' ', [(665.7,'43','6'), (461.2,'57','6')]),
    (3964.2, '15', '?', [(2375.6,'8','4'), (2158.1,'75','12'), (146.5,'17','8')]),
    (3982.2, '5', ' ', [(2721.4,'8','1'), (2158.1,'29','2'), (1230.5,'4','LT'), (146.5,'63','2')]),
    (4075.9, '10', ' ', [(2721.4,'8','2'), (2375.6,'21','2'), (2181.2,'12','2'), (146.5,'59','2')]),
    (4139.9, '15', ' ', [(2158.1,'20','5'), (146.5,'56','5')]),
    (4325.6, '5', ' ', [(2158.1,'100','')]),
    (4352.9, '10', ' ', [(2158.1,'24','2'), (461.2,'9','2'), (0.0,'67','2')]),
    (4416.4, '5', ' ', [(665.7,'39','5'), (461.2,'61','5')]),
