    (4993,   '2', ' ', [(2158.1,'100','')]),
    (5020,   '2', ' ', [(2158.1,'100','')]),
    (5170,   '2', ' ', [(3600.3,'100',''), (146.5,'100','')]),
    (5383,   '2', '?', [(3545.2,'35','4')]),
    (5540,   '2', ' ', [(3600.3,'65','4')]),
