errors = []
total_g = 0
for ei_raw, de_raw, ql, gammas in RAW:
    ei = Decimal(str(ei_raw))
    lrec = lr(ei_raw, de_raw, ql)
    if len(lrec) != 80:
        errors.append(f'L-rec Ei={ei} len={len(lrec)}')
    q_gamma = '?' if ei in TENTATIVE else ' '
    rows = [(ei - Decimal(str(ef)), ri, dri) for ef, ri, dri in gammas]
    rows.sort()
    for eg, ri, dri in rows:
        g = gr(str(eg), ri, dri, q_gamma)
        if len(g) != 80:
            errors.append(f'G-rec Ei={ei} Eg={eg} len={len(g)}')
        total_g += 1

if errors:
    print('ERRORS:')
    for e in errors:
        print(' ', e)
else:
    print(f'ALL OK. Levels={len(RAW)}, G-records={total_g}')
